  Lemma new_old_ids : forall (NEW LB : list block) b b',
    List.NoDup (map blk_id (NEW ++ LB)) -> In b NEW -> In b' LB -> blk_id b <> blk_id b'.
  Proof.
    intros NEW LB b b' ND Hb Hb' E. rewrite map_app in ND.
    revert ND Hb. induction NEW as [|x NEW IH]; intros ND Hb; [exact Hb|].
    cbn in ND. inversion ND as [|y l NI ND']; subst.
    destruct Hb as [<-|Hb]; [| exact (IH ND' Hb)].
    apply NI. apply in_or_app. right. rewrite E. apply in_map. exact Hb'.
  Qed.

  (* [comment removed for export] *)
  Lemma new_old_blocks_disjoint : forall s' NEW LB m' b b',
    as_RHEAP H s' (NEW ++ LB) m' -> In b NEW -> In b' LB ->
    blk_addr b + blk_size b + 16 <= blk_addr b' \/ blk_addr b' + blk_size b' + 16 <= blk_addr b.
  Proof.
    intros s' NEW LB m' b b' HP Hb Hb'.
    apply (ah_disj H HH _ _ _ b b' HP); [apply in_or_app; left; exact Hb| apply in_or_app; right; exact Hb'|].
    eapply new_old_ids; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hb'].
  Qed.
