  Lemma rw_cells_keep_scr : forall LF m0 X XS m m' A cs,
    as_RFS H LF m0 -> fsobj H LF A (Z.of_nat (cells_size cs)) -> aapp A (Z.of_nat (cells_size cs)) ->
    rw_cells asegs m A cs -> munch (X ++ XS) m m' -> wmono asegs m m' -> disjoint_from X A (Z.of_nat (cells_size cs)) ->
    Forall (fs_scratch H LF) XS -> rw_cells asegs m' A cs.
  Proof.
    intros LF m0 X XS m m' A cs RF FO AP RC MU WM DX FS.
    pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
    eapply rw_cells_transport; [exact RC| exact MU| exact WM|]. apply disjoint_from_app. split; [exact DX|].
    eapply (disjoint_scratch H HH); [exact RF| exact FO| lia| lia| exact AP| exact FS].
  Qed.

  Lemma ro_cells_keep_scr : forall LF m0 X XS m m' A cs,
    as_RFS H LF m0 -> fsobj H LF A (Z.of_nat (cells_size cs)) -> aapp A (Z.of_nat (cells_size cs)) ->
    ro_cells asegs m A cs -> munch (X ++ XS) m m' -> disjoint_from X A (Z.of_nat (cells_size cs)) ->
    Forall (fs_scratch H LF) XS -> ro_cells asegs m' A cs.
  Proof.
    intros LF m0 X XS m m' A cs RF FO AP RC MU DX FS.
    pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
    eapply ro_cells_transport; [exact RC| exact MU|]. apply disjoint_from_app. split; [exact DX|].
    eapply (disjoint_scratch H HH); [exact RF| exact FO| lia| lia| exact AP| exact FS].
  Qed.

  (* [comment removed for export] *)
