(* [comment removed for export] *)
  Lemma AStateBlock_mono : forall LB LB' m b ioc implb S ds,
    (forall x, In x LB -> In x LB') -> AStateBlock LB m b ioc implb S ds -> AStateBlock LB' m b ioc implb S ds.
  Proof.
    intros LB LB' m b ioc implb S ds SUB (p & j7 & j16 & j4 & IN & RB & CH & OK & EV & CE & CW & PM & FB & PC & CO & E1 & E2 & E3 & AD).
    exists p, j7, j16, j4. split; [apply SUB; exact IN|]. split; [exact RB|]. split; [exact CH|]. split; [exact OK|]. split; [exact EV|].
    split; [exact CE|]. split; [exact CW|]. split; [exact PM|]. split; [eapply AFlatBuf_mono; [exact SUB| exact FB]|]. split; [exact PC|].
    split; [exact CO|]. split; [exact E1|]. split; [exact E2|]. split; [exact E3|]. exact AD.
  Qed.

